use crate::geometry::{get_bounds, Path64, Paths64, Point64};
use crate::offset::inflate_triangle_raw;

#[derive(Clone, Copy)]
struct Crossing {
    x_mid: f64,
    x0: f64,
    x1: f64,
    delta: i32,
}

fn triangle() -> Path64 {
    vec![
        Point64::new(50, 0),
        Point64::new(100, 100),
        Point64::new(0, 100),
    ]
}

fn segment_intersection_y(
    a1: Point64,
    a2: Point64,
    b1: Point64,
    b2: Point64,
) -> Option<f64> {
    let ax1 = a1.x as f64;
    let ay1 = a1.y as f64;
    let ax2 = a2.x as f64;
    let ay2 = a2.y as f64;
    let bx1 = b1.x as f64;
    let by1 = b1.y as f64;
    let bx2 = b2.x as f64;
    let by2 = b2.y as f64;

    let dax = ax2 - ax1;
    let day = ay2 - ay1;
    let dbx = bx2 - bx1;
    let dby = by2 - by1;
    let denom = dax * dby - day * dbx;
    if denom.abs() < 1e-9 {
        return None;
    }
    let num_a = (bx1 - ax1) * dby - (by1 - ay1) * dbx;
    let num_b = (bx1 - ax1) * day - (by1 - ay1) * dax;
    let ua = num_a / denom;
    let ub = num_b / denom;
    if ua <= 1e-9 || ua >= 1.0 - 1e-9 || ub <= 1e-9 || ub >= 1.0 - 1e-9 {
        return None;
    }
    Some(ay1 + ua * day)
}

fn collect_scan_bands(path: &[Point64]) -> Vec<f64> {
    let mut ys = Vec::new();
    for point in path {
        ys.push(point.y as f64);
    }
    for i in 0..path.len() {
        let a1 = path[i];
        let a2 = path[(i + 1) % path.len()];
        for j in (i + 1)..path.len() {
            let next_j = (j + 1) % path.len();
            if i == j || i == next_j || (i + 1) % path.len() == j {
                continue;
            }
            let b1 = path[j];
            let b2 = path[next_j];
            if let Some(y) = segment_intersection_y(a1, a2, b1, b2) {
                ys.push(y);
            }
        }
    }
    ys.sort_by(|a, b| a.partial_cmp(b).unwrap());
    ys.dedup_by(|a, b| (*a - *b).abs() < 1e-9);
    ys
}

fn active_crossings(path: &[Point64], y0: f64, y1: f64) -> Vec<Crossing> {
    let y_mid = (y0 + y1) * 0.5;
    let mut crossings = Vec::new();
    for idx in 0..path.len() {
        let p1 = path[idx];
        let p2 = path[(idx + 1) % path.len()];
        let py1 = p1.y as f64;
        let py2 = p2.y as f64;
        if (py1 - py2).abs() < 1e-9 {
            continue;
        }
        let ymin = py1.min(py2);
        let ymax = py1.max(py2);
        if !(y_mid > ymin && y_mid < ymax) {
            continue;
        }
        let t_mid = (y_mid - py1) / (py2 - py1);
        let t0 = (y0 - py1) / (py2 - py1);
        let t1 = (y1 - py1) / (py2 - py1);
        let px1 = p1.x as f64;
        let px2 = p2.x as f64;
        crossings.push(Crossing {
            x_mid: px1 + (px2 - px1) * t_mid,
            x0: px1 + (px2 - px1) * t0,
            x1: px1 + (px2 - px1) * t1,
            delta: if py2 > py1 { 1 } else { -1 },
        });
    }
    crossings.sort_by(|a, b| a.x_mid.partial_cmp(&b.x_mid).unwrap());
    crossings
}

fn filled_area(path: &[Point64]) -> f64 {
    if path.len() < 3 {
        return 0.0;
    }
    let bands = collect_scan_bands(path);
    if bands.len() < 2 {
        return 0.0;
    }
    let mut area = 0.0;
    for pair in bands.windows(2) {
        let y0 = pair[0];
        let y1 = pair[1];
        if y1 - y0 < 1e-9 {
            continue;
        }
        let crossings = active_crossings(path, y0, y1);
        let mut winding = 0;
        let mut left: Option<Crossing> = None;
        for crossing in crossings {
            if let Some(left_cross) = left {
                if winding > 0 {
                    let width0 = crossing.x0 - left_cross.x0;
                    let width1 = crossing.x1 - left_cross.x1;
                    area += (width0 + width1) * (y1 - y0) * 0.5;
                }
            }
            winding += crossing.delta;
            left = Some(crossing);
        }
    }
    area
}

pub fn compute_area_twice(offset: i64) -> i128 {
    let intersected = triangle();
    let offset_path = inflate_triangle_raw(&intersected, offset);
    let offset_result: Paths64 = if offset_path.is_empty() {
        Vec::new()
    } else {
        vec![offset_path]
    };

