use crate::geometry::{Path64, Point64};

const ARC_TOLERANCE: f64 = 0.25;

#[derive(Clone, Copy, Debug, PartialEq)]
struct Normal {
    x: f64,
    y: f64,
}

impl Normal {
    fn cross(self, other: Self) -> f64 {
        self.x * other.y - self.y * other.x
    }

    fn dot(self, other: Self) -> f64 {
        self.x * other.x + self.y * other.y
    }
}

fn round_i64(value: f64) -> i64 {
    value.round() as i64
}

fn to_point(center: Point64, normal: Normal, delta: f64) -> Point64 {
    Point64::new(
        round_i64(center.x as f64 + normal.x * delta),
        round_i64(center.y as f64 + normal.y * delta),
    )
}

fn edge_normals(path: &[Point64]) -> Vec<Normal> {
    let mut normals = Vec::with_capacity(path.len());
    for window in path.windows(2) {
        let p1 = window[0];
        let p2 = window[1];
        let dx = (p2.x - p1.x) as f64;
        let dy = (p2.y - p1.y) as f64;
        let len = (dx * dx + dy * dy).sqrt();
        normals.push(Normal {
            x: dy / len,
            y: -dx / len,
        });
    }
    let p1 = *path.last().unwrap();
    let p2 = path[0];
    let dx = (p2.x - p1.x) as f64;
    let dy = (p2.y - p1.y) as f64;
    let len = (dx * dx + dy * dy).sqrt();
    normals.push(Normal {
        x: dy / len,
        y: -dx / len,
    });
    normals
}

fn arc_steps_per_radian(delta: f64) -> f64 {
    let delta = delta.abs();
    if delta == 0.0 {
        return 0.0;
    }
    let tol = ARC_TOLERANCE.min(delta * 0.25);
    let steps_per_circle = std::f64::consts::PI / (1.0 - tol / delta).acos();
    steps_per_circle / (std::f64::consts::PI * 2.0)
}

fn push_unique(path: &mut Path64, point: Point64) {
    if path.last().copied() != Some(point) {
        path.push(point);
    }
}

fn push_round(
    out: &mut Path64,
    center: Point64,
    prev: Normal,
    curr: Normal,
    delta: f64,
    steps_per_radian: f64,
) {
    let angle = prev.cross(curr).atan2(prev.dot(curr));
    let steps = (steps_per_radian * angle.abs()).ceil().max(1.0) as usize;
    let start = prev.y.atan2(prev.x);
    let step = angle / steps as f64;
    for idx in 0..steps {
        let theta = start + step * idx as f64;
        let point = Point64::new(
            round_i64(center.x as f64 + theta.cos() * delta),
            round_i64(center.y as f64 + theta.sin() * delta),
        );
        push_unique(out, point);
    }
    push_unique(out, to_point(center, curr, delta));
}

pub fn inflate_triangle_raw(path: &[Point64], offset: i64) -> Path64 {
    if path.len() != 3 || offset == 0 {
        return path.to_vec();
    }

    let delta = offset as f64;
    let normals = edge_normals(path);
    let steps_per_radian = arc_steps_per_radian(delta);
    let mut out = Vec::new();

    for idx in 0..path.len() {
        let prev_idx = if idx == 0 { path.len() - 1 } else { idx - 1 };
        let prev = normals[prev_idx];
        let curr = normals[idx];
        let sin_a = prev.cross(curr);
        let point = path[idx];
        if sin_a * delta >= 0.0 {
            push_round(&mut out, point, prev, curr, delta, steps_per_radian);
        } else {
            push_unique(&mut out, to_point(point, prev, delta));
            push_unique(&mut out, point);
            push_unique(&mut out, to_point(point, curr, delta));
        }
    }

    out
}

