#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct Point64 {
    pub x: i64,
    pub y: i64,
}

impl Point64 {
    pub const fn new(x: i64, y: i64) -> Self {
        Self { x, y }
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct Rect64 {
    pub left: i64,
    pub top: i64,
    pub right: i64,
    pub bottom: i64,
}

pub type Path64 = Vec<Point64>;
pub type Paths64 = Vec<Path64>;

pub fn get_bounds(paths: &[Path64]) -> Option<Rect64> {
    let mut iter = paths.iter().flat_map(|path| path.iter());
    let first = *iter.next()?;
    let mut rect = Rect64 {
        left: first.x,
        top: first.y,
        right: first.x,
        bottom: first.y,
    };
    for point in iter {
        rect.left = rect.left.min(point.x);
        rect.top = rect.top.min(point.y);
        rect.right = rect.right.max(point.x);
        rect.bottom = rect.bottom.max(point.y);
    }
    Some(rect)
}

