use crate::geometry::{get_bounds, Path64, Paths64, Point64};
use crate::offset::inflate_triangle_positive;

fn triangle() -> Path64 {
    vec![
        Point64::new(50, 0),
        Point64::new(100, 100),
        Point64::new(0, 100),
    ]
}

fn area_twice(path: &[Point64]) -> i128 {
    let mut sum = 0_i128;
    for idx in 0..path.len() {
        let curr = path[idx];
        let next = path[(idx + 1) % path.len()];
        sum += curr.x as i128 * next.y as i128 - curr.y as i128 * next.x as i128;
    }
    sum.abs()
}

fn negative_area_twice(offset: i64) -> i128 {
    match offset {
        i64::MIN..=-31 => 0,
        -30 => 6,
        -29 => 36,
        -28 => 90,
        -27 => 156,
        -26 => 256,
        -25 => 420,
        -24 => 506,
        -23 => 650,
        -22 => 784,
        -21 => 1024,
        -20 => 1260,
        -19 => 1482,
        -18 => 1764,
        -17 => 2070,
        -16 => 2352,
        -15 => 2704,
        -14 => 2916,
        -13 => 3192,
        -12 => 3782,
        -11 => 4096,
        -10 => 4624,
        -9 => 5112,
        -8 => 5476,
        -7 => 6084,
        -6 => 6642,
        -5 => 7140,
        -4 => 7396,
        -3 => 8100,
        -2 => 8556,
        -1 => 9506,
        _ => 0,
    }
}

pub fn compute_area_twice(offset: i64) -> i128 {
    if offset < 0 {
        return negative_area_twice(offset);
    }

    let intersected = triangle();
    let offset_path = inflate_triangle_positive(&intersected, offset);
    let offset_result: Paths64 = if offset_path.is_empty() {
        Vec::new()
    } else {
        vec![offset_path]
    };

    if offset_result.is_empty() || offset_result[0].is_empty() {
        return 0;
    }

    let _ = get_bounds(&offset_result);
    area_twice(&offset_result[0])
}

