use crate::geometry::{Path64, Point64};

const DEFAULT_ARC_RATIO: f64 = 0.002;

#[derive(Clone, Copy, Debug, PartialEq)]
struct Normal {
    x: f64,
    y: f64,
}

impl Normal {
    fn cross(self, other: Self) -> f64 {
        self.x * other.y - self.y * other.x
    }

    fn dot(self, other: Self) -> f64 {
        self.x * other.x + self.y * other.y
    }
}

fn round_i64(value: f64) -> i64 {
    value.round() as i64
}

fn edge_normals(path: &[Point64]) -> Vec<Normal> {
    let mut normals = Vec::with_capacity(path.len());
    for idx in 0..path.len() {
        let p1 = path[idx];
        let p2 = path[(idx + 1) % path.len()];
        let dx = (p2.x - p1.x) as f64;
        let dy = (p2.y - p1.y) as f64;
        let len = (dx * dx + dy * dy).sqrt();
        normals.push(Normal {
            x: dy / len,
            y: -dx / len,
        });
    }
    normals
}

fn steps_per_circle(delta: f64) -> f64 {
    let delta = delta.abs();
    if delta == 0.0 {
        return 0.0;
    }
    let ratio = DEFAULT_ARC_RATIO;
    (std::f64::consts::PI * delta)
        .min(std::f64::consts::PI / (1.0 - ratio).acos())
}

fn push_unique(path: &mut Path64, point: Point64) {
    if path.last().copied() != Some(point) {
        path.push(point);
    }
}

pub fn inflate_triangle_positive(path: &[Point64], offset: i64) -> Path64 {
    if path.len() != 3 || offset <= 0 {
        return path.to_vec();
    }

    let delta = offset as f64;
    let normals = edge_normals(path);
    let steps_per_circle = steps_per_circle(delta);
    let steps_per_radian = steps_per_circle / (std::f64::consts::PI * 2.0);
    let step_angle = (std::f64::consts::PI * 2.0) / steps_per_circle;
    let step_cos = step_angle.cos();
    let step_sin = step_angle.sin();
    let mut out = Vec::new();

    for idx in 0..path.len() {
        let prev_idx = if idx == 0 { path.len() - 1 } else { idx - 1 };
        let center = path[idx];
        let prev = normals[prev_idx];
        let curr = normals[idx];
        let angle = prev.cross(curr).atan2(prev.dot(curr));
        let steps = (steps_per_radian * angle.abs()).ceil().max(1.0) as usize;

        let mut off_x = prev.x * delta;
        let mut off_y = prev.y * delta;
        push_unique(
            &mut out,
            Point64::new(
                round_i64(center.x as f64 + off_x),
                round_i64(center.y as f64 + off_y),
            ),
        );

        for _ in 1..steps {
            let next_x = off_x * step_cos - off_y * step_sin;
            let next_y = off_x * step_sin + off_y * step_cos;
            off_x = next_x;
            off_y = next_y;
            push_unique(
                &mut out,
                Point64::new(
                    round_i64(center.x as f64 + off_x),
                    round_i64(center.y as f64 + off_y),
                ),
            );
        }

        push_unique(
            &mut out,
            Point64::new(
                round_i64(center.x as f64 + curr.x * delta),
                round_i64(center.y as f64 + curr.y * delta),
            ),
        );
    }

    out
}

