fn trim_trailing_zeros(mut text: String) -> String {
    if text.contains('.') {
        while text.ends_with('0') {
            text.pop();
        }
        if text.ends_with('.') {
            text.pop();
        }
    }
    if text == "-0" {
        text.clear();
        text.push('0');
    }
    text
}

pub fn format_cpp_double(value: f64) -> String {
    if value == 0.0 {
        return "0".to_string();
    }

    let abs = value.abs();
    let precision = 6_i32;
    let exp10 = abs.log10().floor() as i32;

    if exp10 < -4 || exp10 >= precision {
        let digits = (precision - 1).max(0) as usize;
        let mut text = format!("{value:.*e}", digits);
        if let Some(idx) = text.find('e') {
            let mantissa = trim_trailing_zeros(text[..idx].to_string());
            let exponent = &text[idx + 1..];
            let sign = if exponent.starts_with('-') { '-' } else { '+' };
            let digits = exponent.trim_start_matches(['+', '-']).trim_start_matches('0');
            let digits = if digits.is_empty() { "0" } else { digits };
            text = format!("{mantissa}e{sign}{digits}");
        }
        text
    } else {
        let frac_digits = (precision - exp10 - 1).max(0) as usize;
        trim_trailing_zeros(format!("{value:.*}", frac_digits))
    }
}

